questionvariables.text:
/* Design backwards: choose tan(theta) = k first, then show it as m*tan(theta) = m*k.
   k = sg*t with t in {1/sqrt(3), 1, sqrt(3)} (reference angle 30, 45 or 60 degrees),
   sg = +1 or -1, m in {1, 2, 3, 4}: 2 x 3 x 4 = 24 distinct variants. */
idx : 1 + rand(3);
tlist : [1/sqrt(3), 1, sqrt(3)];
alist : [30, 45, 60];
t : tlist[idx];
alpha : alist[idx];
sg : rand([-1, 1]);
m : rand([1, 2, 3, 4]);
k : sg*t;                          /* tan(theta) = k */
given_value : k;
rhs : m*k;
eqn : m*tan(theta) = rhs;

/* Quadrants: tan is positive in I and III, negative in II and IV */
qlist : if sg = 1 then [1, 3] else [2, 4];
qset : setify(qlist);
wrongqset : if sg = 1 then {2, 4} else {1, 3};
qopts : [[1, is(member(1, qlist)), "Quadrant I"], [2, is(member(2, qlist)), "Quadrant II"],
         [3, is(member(3, qlist)), "Quadrant III"], [4, is(member(4, qlist)), "Quadrant IV"]];
ta_quad1 : qlist[1];
ta_quad2 : qlist[2];

/* Solutions in 0 <= theta < 360 */
ta1 : if sg = 1 then alpha else 180 - alpha;
ta2 : if sg = 1 then 180 + alpha else 360 - alpha;
/* Solutions of tan(theta) = -k: the common sign mistake */
w1 : if sg = 1 then 180 - alpha else alpha;
w2 : if sg = 1 then 360 - alpha else 180 + alpha;

/* Possible student mistakes in (a) */
alpha_rad : alpha*%pi/180;         /* reference angle in radians */
alpha_comp : 90 - alpha;           /* used 1/k, i.e. the other acute angle */

feedbackvariables.text:
ok : is(ans1 = ta1 or ans1 = ta2);
outr : is(ans1 + 360 = ta1 or ans1 + 360 = ta2 or ans1 - 360 = ta1 or ans1 - 360 = ta2);
wsign : is(ans1 = w1 or ans1 = w2);
inrad : is(ans1 = ta1*%pi/180 or ans1 = ta2*%pi/180);

ok : is(ans2 = ta1 or ans2 = ta2);
dup : is(ans2 = ans1);
outr : is(ans2 + 360 = ta1 or ans2 + 360 = ta2 or ans2 - 360 = ta1 or ans2 - 360 = ta2);
wsign : is(ans2 = w1 or ans2 = w2);
inrad : is(ans2 = ta1*%pi/180 or ans2 = ta2*%pi/180);
okdistinct : is(ok and not dup);
